-- Migration: Year 2 - Reproductive Pathology MCQs Part 3 (161-240)
-- Date: 2026-04-24

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- Ensure Topic exists
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Reproductive Pathology', 'reproductive-pathology', 3, 2, 60)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- FEMALE: SEX CORD-STROMAL TUMORS & METASTATIC OVARIAN TUMORS (161-175)
    (v_topic_id, '161. Granulosa-Theca cell tumors are neoplasms of the sex cord-stroma. What hormone do they typically produce in large amounts?', '["Testosterone", "Estrogen", "Progesterone", "hCG"]', 1, 'Granulosa cells produce estrogen. These tumors are highly estrogenic, causing precocious puberty in kids, heavy menses in adults, and postmenopausal bleeding in the elderly.'),
    (v_topic_id, '162. A 60-year-old woman with a Granulosa-Theca cell tumor presents with vaginal bleeding. An endometrial biopsy is performed. What is the most likely finding?', '["Atrophic endometrium", "Endometrial hyperplasia or carcinoma", "Acute endometritis", "Adenomyosis"]', 1, 'The massive unopposed estrogen produced by the tumor drives endometrial hyperplasia, greatly increasing the risk of concurrent endometrial carcinoma.'),
    (v_topic_id, '163. What is the classic histological finding in a Granulosa cell tumor?', '["Call-Exner bodies", "Reinke crystals", "Schiller-Duval bodies", "Psammoma bodies"]', 0, 'Call-Exner bodies are small, fluid-filled spaces surrounded by granulosa cells in a rosette pattern, resembling primitive primordial follicles.'),
    (v_topic_id, '164. A Sertoli-Leydig cell tumor of the ovary produces massive amounts of which hormone?', '["Estrogen", "Androgens (Testosterone)", "Progesterone", "Cortisol"]', 1, 'Just like in the testes, Leydig cells produce androgens. In a female, this tumor causes rapid-onset virilization (hirsutism, male-pattern baldness, clitoromegaly, deepening of the voice).'),
    (v_topic_id, '165. What pathognomonic finding is seen on histology in the Leydig cells of a Sertoli-Leydig tumor?', '["Call-Exner bodies", "Psammoma bodies", "Reinke crystals", "Fried egg cells"]', 2, 'Reinke crystals (eosinophilic, rod-shaped crystals) are pathognomonic for Leydig cells.'),
    (v_topic_id, '166. A Fibroma is a benign tumor of fibroblasts in the ovarian stroma. It classically presents with Meigs Syndrome. What is Meigs Syndrome?', '["Ovarian fibroma, Ascites, and Right-sided Pleural Effusion", "Ovarian fibroma, Deep Vein Thrombosis, and Pulmonary Embolism", "Ovarian fibroma, Endometrial cancer, and Breast cancer", "Ovarian fibroma, Hyperthyroidism, and Glaucoma"]', 0, 'Meigs syndrome triad: Ovarian fibroma, severe ascites, and a right-sided pleural effusion. Removing the benign fibroma cures the ascites and effusion completely.'),
    (v_topic_id, '167. Grossly, how does an ovarian Fibroma appear?', '["A large, fluid-filled cyst", "A solid, hard, pale white mass", "A hemorrhagic, necrotic mass", "A yellow, fatty mass"]', 1, 'Fibromas are dense bundles of spindle cells (fibroblasts), making them completely solid, hard, and white (resembling a fibroid but in the ovary).'),
    (v_topic_id, '168. A Krukenberg Tumor is a metastatic tumor to the ovary. Where is the most common primary site?', '["Breast", "Lungs", "Diffuse-type Gastric Carcinoma", "Colon"]', 2, 'Diffuse-type gastric carcinoma classically metastasizes bilaterally to the ovaries. It is composed of mucin-secreting signet ring cells.'),
    (v_topic_id, '169. What is the defining histological feature of a Krukenberg tumor?', '["Reinke crystals", "Signet ring cells", "Call-Exner bodies", "Psammoma bodies"]', 1, 'Signet ring cells have a massive mucin vacuole that pushes the nucleus to the extreme periphery of the cell, making it look like a signet ring.'),
    (v_topic_id, '170. If an ovarian tumor is found to be BILATERAL, is it more likely a primary ovarian cancer or a metastasis?', '["Primary surface epithelial tumor", "Primary germ cell tumor", "Metastatic tumor (e.g., Krukenberg)", "Sex cord-stromal tumor"]', 2, 'While serous carcinomas can be bilateral, massive solid bilateral ovarian masses are strongly suspicious for metastasis (Krukenberg). Primary germ cell and sex-cord tumors are almost always unilateral.'),
    (v_topic_id, '171. A Pseudomyxoma Peritonei ("jelly belly") is most often caused by metastasis to the ovary from which primary organ?', '["Stomach", "Appendix", "Colon", "Breast"]', 1, 'A mucinous tumor of the appendix can rupture, seeding the peritoneum and the ovaries, producing massive amounts of thick mucin.'),
    (v_topic_id, '172. Which ovarian tumor is derived from all three germ layers (ectoderm, mesoderm, endoderm)?', '["Dysgerminoma", "Mature cystic teratoma", "Yolk sac tumor", "Brenner tumor"]', 1, 'Teratomas are pluripotent, forming skin/hair (ectoderm), bone/cartilage (mesoderm), and gut/thyroid (endoderm).'),
    (v_topic_id, '173. A patient has a benign ovarian mass that grossly looks pale yellow-tan and solid. Histology shows nests of transitional-type epithelium. Diagnosis?', '["Brenner tumor", "Fibroma", "Granulosa cell tumor", "Endometrioma"]', 0, 'Brenner tumors ("B" for Bladder) have urothelium-like transitional cells nestled within a dense fibrous stroma (giving the pale yellow-tan color).'),
    (v_topic_id, '174. A 15-year-old girl has never had a menstrual period (primary amenorrhea). She is tall and has normal breast development but absent axillary and pubic hair. She has a blind vaginal pouch and no uterus. Karyotype is 46,XY. Diagnosis?', '["Turner Syndrome (45,XO)", "Mullerian Agenesis", "Androgen Insensitivity Syndrome", "5-alpha-reductase deficiency"]', 2, 'AIS involves a mutated androgen receptor. The testes (internal) make testosterone and MIH. MIH destroys the Mullerian structures (no uterus/upper vagina). Testosterone cannot act on receptors, so there is no male external genitalia or body hair. The excess testosterone is aromatized to estrogen, causing breast development.'),
    (v_topic_id, '175. Why must the internal testes be surgically removed in a patient with Androgen Insensitivity Syndrome?', '["They cause severe pain", "They will cause virilization eventually", "High risk of developing a germ cell tumor (e.g., Dysgerminoma/Seminoma)", "They secrete toxic levels of estrogen"]', 2, 'Cryptorchid/internal testes in AIS have a high risk of malignant transformation after puberty.'),

    -- BREAST PATHOLOGY: INFLAMMATORY & BENIGN CONDITIONS (176-200)
    (v_topic_id, '176. What is the most common cause of Acute Mastitis?', '["Staphylococcus aureus infection during breastfeeding", "Autoimmune destruction of ducts", "Trauma to the breast", "Ductal ectasia"]', 0, 'Fissures in the nipple during breastfeeding allow skin flora (S. aureus) to enter, causing an erythematous, painful, purulent infection.'),
    (v_topic_id, '177. How is Acute Mastitis managed?', '["Immediately stop breastfeeding and surgically drain", "Continue breastfeeding and prescribe antibiotics (e.g., Dicloxacillin)", "Prescribe corticosteroids", "Mastectomy"]', 1, 'Continued emptying of the breast is essential to prevent abscess formation. Safe antibiotics (like dicloxacillin) resolve the infection.'),
    (v_topic_id, '178. A patient presents with a subareolar mass and nipple retraction. She is a heavy smoker. Histology shows squamous metaplasia of the lactiferous ducts. Diagnosis?', '["Invasive ductal carcinoma", "Periductal Mastitis", "Fat necrosis", "Fibroadenoma"]', 1, 'Smoking causes a relative Vitamin A deficiency in the breast ducts, leading to squamous metaplasia. Keratin blocks the ducts, causing inflammation, fibrosis, and nipple retraction.'),
    (v_topic_id, '179. Mammary Duct Ectasia presents with a green-brown nipple discharge and a periareolar mass. It is characterized histologically by?', '["Massive numbers of plasma cells", "Squamous metaplasia", "Atypical ductal hyperplasia", "Malignant glands"]', 0, 'Also known as Plasma Cell Mastitis. It is a rare, non-bacterial chronic inflammation of the major ducts in multiparous postmenopausal women, featuring prominent plasma cells.'),
    (v_topic_id, '180. A woman was in a car accident and the seatbelt severely bruised her breast. She now has a painless, hard lump. Mammogram shows abnormal calcification. Biopsy shows necrotic fat and giant cells. Diagnosis?', '["Invasive ductal carcinoma", "Fibrocystic change", "Fat Necrosis", "Fibroadenoma"]', 2, 'Trauma causes saponification of fat, leading to a hard, calcified mass that perfectly mimics breast cancer both clinically and on mammography. Biopsy is required to prove it is benign fat necrosis.'),
    (v_topic_id, '181. What is the most common benign change in the breast in premenopausal women?', '["Fibroadenoma", "Intraductal papilloma", "Fibrocystic Change", "Phyllodes tumor"]', 2, 'Fibrocystic changes are hormone-mediated (worsen right before menstruation) and present as lumpy, painful breasts ("blue-dome cysts" on gross exam).'),
    (v_topic_id, '182. Fibrocystic change involves several morphologic variations. Which of the following carries NO increased risk for developing breast carcinoma?', '["Atypical ductal hyperplasia", "Sclerosing adenosis", "Apocrine metaplasia and simple cysts", "Atypical lobular hyperplasia"]', 2, 'Simple cysts, fibrosis, and apocrine metaplasia have ZERO increased risk of cancer. (Note: Apocrine metaplasia is the ONLY metaplasia that does not increase cancer risk!).'),
    (v_topic_id, '183. Which fibrocystic change is characterized by an increased number of acini compressed by dense fibrotic stroma, often containing calcifications on mammography?', '["Apocrine metaplasia", "Sclerosing Adenosis", "Intraductal papilloma", "Fat necrosis"]', 1, 'Sclerosing adenosis can mimic cancer physically (hard mass) and radiologically (calcifications), and it carries a 2x increased risk of developing carcinoma.'),
    (v_topic_id, '184. Atypical Ductal Hyperplasia (ADH) carries what level of risk for developing invasive carcinoma?', '["No increased risk", "2x increased risk", "5x increased risk", "10x increased risk"]', 2, 'Atypical hyperplasia (ductal or lobular) carries a 5x increased risk of cancer, which applies to BOTH breasts, not just the one with the hyperplasia.'),
    (v_topic_id, '185. A 35-year-old premenopausal woman presents with a bloody nipple discharge. There are no palpable masses. What is the most likely diagnosis?', '["Invasive ductal carcinoma", "Intraductal Papilloma", "Fibroadenoma", "Paget disease of the breast"]', 1, 'Intraductal papilloma is a benign fibrovascular projection into a major lactiferous duct. As it twists and turns, it easily bleeds, causing bloody discharge.'),
    (v_topic_id, '186. How can you differentiate a benign Intraductal Papilloma from a malignant Papillary Carcinoma?', '["Papilloma has an overlying layer of myoepithelial cells; Carcinoma does NOT", "Papilloma lacks myoepithelial cells", "Carcinoma occurs only in males", "Papilloma does not bleed"]', 0, 'Benign papillomas maintain the normal 2-layer structure (epithelial cells + myoepithelial cells). Malignant papillary carcinomas lack the myoepithelial layer and are more common in older women.'),
    (v_topic_id, '187. What is the most common benign breast tumor in females under age 35?', '["Fibroadenoma", "Phyllodes tumor", "Intraductal papilloma", "DCIS"]', 0, 'Fibroadenoma is a highly mobile, firm, rubbery, painless mass. It is highly estrogen-sensitive (grows in pregnancy, shrinks in menopause).'),
    (v_topic_id, '188. True or False: Fibroadenomas carry a high risk of transforming into invasive carcinoma.', '["True, requires immediate mastectomy", "False, there is no increased risk of cancer", "True, but only after menopause", "True, but only in BRCA carriers"]', 1, 'Fibroadenomas are completely benign and have no increased risk of progression to breast cancer.'),
    (v_topic_id, '189. A 55-year-old postmenopausal woman presents with a rapidly growing, massive breast tumor. Biopsy shows hypercellular stroma with "leaf-like" projections. Diagnosis?', '["Fibroadenoma", "Phyllodes Tumor", "Inflammatory Breast Cancer", "Sclerosing adenosis"]', 1, 'Phyllodes tumors are fibroadenoma-like tumors that arise from the stroma. The stroma overgrows rapidly, creating "leaf-like" (phyllodes) lobulations. They can be benign, borderline, or frankly malignant.'),
    (v_topic_id, '190. What is the most important prognostic factor for breast cancer?', '["Tumor size", "Histologic grade", "Axillary lymph node metastasis", "Estrogen receptor status"]', 2, 'While distant metastasis is the ultimate cause of death, the single most important PROGNOSTIC factor at the time of diagnosis is whether it has spread to the axillary lymph nodes (assessed via sentinel node biopsy).'),

    -- BREAST: DCIS & NON-INVASIVE CARCINOMA (191-210)
    (v_topic_id, '191. Ductal Carcinoma In Situ (DCIS) is a malignant proliferation of cells within the ducts. Does it present as a palpable mass?', '["Yes, it is typically a massive hard lump", "No, it is usually clinically silent and detected only as microcalcifications on screening mammography", "Yes, it presents with severe pain", "Yes, it presents with nipple retraction"]', 1, 'DCIS does not form a mass because it is contained within the duct. As the center of the duct outgrows its blood supply, it necroses and calcifies, which is picked up on mammograms.'),
    (v_topic_id, '192. Which subtype of DCIS is characterized by high-grade cells with extensive central necrosis and dystrophic calcification?', '["Comedocarcinoma", "Papillary DCIS", "Cribriform DCIS", "Solid DCIS"]', 0, 'Comedo DCIS is aggressive. The center of the duct is filled with dead, necrotic "cheese-like" material (comedonecrosis) that calcifies heavily.'),
    (v_topic_id, '193. A patient presents with an erythematous, scaly, crusty, ulcerated nipple. Biopsy of the epidermis shows large cells with clear halos. Diagnosis?', '["Eczema", "Paget Disease of the Breast", "Inflammatory breast cancer", "Malignant melanoma"]', 1, 'Paget disease occurs when malignant DCIS cells migrate up the lactiferous ducts and invade the skin of the nipple/areola.'),
    (v_topic_id, '194. True or False: Paget disease of the breast is almost always associated with an underlying carcinoma.', '["True", "False, it is always an isolated skin condition", "False, it only occurs in males", "False, it is caused by a virus"]', 0, 'Unlike Extramammary Paget disease of the vulva, breast Paget disease is almost 100% associated with an underlying DCIS or invasive carcinoma in the breast tissue.'),
    (v_topic_id, '195. Lobular Carcinoma In Situ (LCIS) involves malignant proliferation in the lobules. How is it usually discovered?', '["It causes massive microcalcifications on mammogram", "It presents as a hard, immobile mass", "It is usually an incidental finding on biopsy performed for another reason", "It causes a bloody nipple discharge"]', 2, 'LCIS does NOT produce a mass and does NOT typically calcify. It is usually found by accident when biopsying a nearby fibrocystic change.'),
    (v_topic_id, '196. What is the pathognomonic cellular defect in LCIS that causes the cells to lose their cohesiveness?', '["Loss of E-cadherin expression", "Mutation in p53", "Overexpression of HER2", "Mutation in BRCA1"]', 0, 'E-cadherin is the "glue" that holds epithelial cells together. Loss of E-cadherin means the cells grow detached and do not form ducts or masses.'),
    (v_topic_id, '197. LCIS is often bilateral and multifocal. What is its clinical significance?', '["It requires bilateral radical mastectomy", "It indicates an increased risk of developing invasive carcinoma in EITHER breast", "It always progresses to Invasive Lobular Carcinoma within 1 year", "It is completely benign and requires no follow-up"]', 1, 'LCIS is considered a "marker" for increased risk (roughly 1% per year) of developing invasive cancer in BOTH breasts (not necessarily lobular either; it can be ductal!). Treatment is usually close surveillance or Tamoxifen.'),
    (v_topic_id, '198. Which quadrant of the breast is the most common site for breast cancer?', '["Upper inner quadrant", "Lower inner quadrant", "Upper outer quadrant", "Lower outer quadrant"]', 2, 'The Upper Outer Quadrant contains the highest density of breast tissue (the Tail of Spence).'),
    (v_topic_id, '199. What causes the "dimpling" of the skin (peau d''orange) in advanced invasive breast cancer?', '["The tumor pulling on the suspensory ligaments (Cooper ligaments)", "The tumor blocking dermal lymphatics, causing lymphedema and swelling around the hair follicles", "The tumor invading the epidermis", "Direct necrosis of the skin"]', 1, 'Blockage of lymphatics by tumor cells causes severe edema of the skin. The skin swells, but the hair follicles are tethered down, creating the pitted appearance of an orange peel (Peau d''orange).'),
    (v_topic_id, '200. What causes retraction of the nipple in invasive breast cancer?', '["Blockage of lymphatics", "Tumor invasion and fibrosis pulling on the suspensory ligaments (Cooper ligaments) and lactiferous ducts", "Destruction of the areola", "Hypertrophy of the nipple muscle"]', 1, 'Desmoplastic response (fibrosis/scarring) caused by the invasive tumor pulls and tethers the skin and nipple inward.'),

    -- BREAST: INVASIVE CARCINOMA (201-225)
    (v_topic_id, '201. Invasive Ductal Carcinoma (IDC) is the most common type of invasive breast cancer (>80%). What is the classic histological presentation?', '["Single file lines of cells", "Duct-like structures floating in a dense, desmoplastic (fibrous) stroma", "Sheets of lymphocytes", "Massive mucin lakes"]', 1, 'IDC forms hard, rock-solid masses because it provokes a massive desmoplastic (scar tissue) response from the surrounding stroma.'),
    (v_topic_id, '202. Tubular Carcinoma is a subtype of IDC. It is characterized by well-differentiated tubules lacking myoepithelial cells. What is its prognosis?', '["Extremely poor", "Excellent prognosis", "100% mortality within 5 years", "Always bilateral"]', 1, 'Tubular carcinoma is very well-differentiated and has an excellent prognosis.'),
    (v_topic_id, '203. Mucinous Carcinoma is a subtype of IDC typically seen in elderly women (>70). Histologically, it shows?', '["Tumor cells floating in massive pools of extracellular mucin", "Cells with single-file lines", "Comedonecrosis", "Fibrous desmoplasia"]', 0, 'It grows slowly and has a good prognosis.'),
    (v_topic_id, '204. Medullary Carcinoma is a subtype of IDC characterized by large, high-grade cells in sheets surrounded by a massive infiltrate of lymphocytes and plasma cells. Which genetic mutation is it highly associated with?', '["BRCA1", "BRCA2", "HER2", "PTEN"]', 0, 'Medullary carcinoma is uniquely associated with BRCA1 mutations. Despite having high-grade cells, the massive immune response (lymphocytes) gives it a surprisingly good prognosis.'),
    (v_topic_id, '205. Inflammatory Breast Carcinoma is the most aggressive subtype of breast cancer. How does it present clinically?', '["A small, painless, hard lump", "An erythematous, swollen, warm, painful breast mimicking acute mastitis", "Bloody nipple discharge", "A slow-growing cyst"]', 1, 'It looks exactly like mastitis but does not respond to antibiotics. It is essentially a clinical diagnosis based on the swollen, red, peau d''orange appearance.'),
    (v_topic_id, '206. What is the pathological mechanism of Inflammatory Breast Carcinoma?', '["Invasion of the dermal lymphatic spaces by tumor cells", "Bacterial co-infection", "Massive hemorrhage into the breast", "Rupture of a cyst"]', 0, 'The tumor cells physically plug the dermal lymphatics, causing severe lymphedema and the inflammatory appearance. Prognosis is very poor.'),
    (v_topic_id, '207. Invasive Lobular Carcinoma (ILC) accounts for ~10% of breast cancers. What is the classic histological presentation?', '["Formation of ducts in a desmoplastic stroma", "Single-file lines of cells (Indian file) infiltrating the stroma", "Pools of mucin", "Sheets of lymphocytes"]', 1, 'Due to the loss of E-cadherin, the cells cannot stick together to form ducts or masses. Instead, they march through the stroma in single-file lines.'),
    (v_topic_id, '208. Because ILC lacks E-cadherin, how does its clinical presentation differ from IDC?', '["It forms a much harder, larger mass", "It often does NOT form a palpable mass or mammographic density, making it very hard to detect", "It always calcifies", "It only occurs in men"]', 1, 'Without desmoplasia or cohesive mass formation, ILC is stealthy. It is also frequently bilateral and multifocal.'),
    (v_topic_id, '209. Estrogen Receptor (ER) and Progesterone Receptor (PR) positivity in a breast tumor indicates?', '["The tumor is highly aggressive and untreatable", "The tumor is dependent on hormones for growth and is amenable to anti-estrogen therapy (e.g., Tamoxifen)", "The tumor will not respond to any treatment", "The patient must undergo bilateral mastectomy"]', 1, 'ER/PR positive tumors have a better prognosis because they can be targeted with endocrine therapies (Tamoxifen, Letrozole).'),
    (v_topic_id, '210. HER2/neu (ERBB2) is an epidermal growth factor receptor. What does HER2 amplification indicate?', '["A slower-growing, benign tumor", "An aggressive tumor that can be specifically targeted with Trastuzumab (Herceptin)", "A tumor that requires testosterone", "A tumor caused by HPV"]', 1, 'HER2 amplification is an aggressive feature, but Trastuzumab (a monoclonal antibody against HER2) has revolutionized treatment and improved survival.'),
    (v_topic_id, '211. What defines "Triple-Negative" breast cancer?', '["Negative for ER, PR, and HER2", "Negative for BRCA1, BRCA2, and p53", "Negative for lymph nodes, metastasis, and recurrence", "Negative for pain, mass, and discharge"]', 0, 'Triple-negative tumors are highly aggressive and carry a poor prognosis because there are no targeted receptors to attack. They are highly associated with BRCA1 mutations.'),
    (v_topic_id, '212. BRCA1 mutations are highly associated with which two cancers?', '["Breast and Ovarian (Serous Carcinoma)", "Breast and Colon", "Breast and Endometrial", "Breast and Lung"]', 0, 'BRCA1 carriers have a tremendous risk of developing both breast and serous ovarian carcinoma.'),
    (v_topic_id, '213. BRCA2 mutations are associated with breast cancer in women and which uniquely male cancer?', '["Prostate cancer", "Testicular Seminoma", "Male Breast Cancer", "Penile carcinoma"]', 2, 'While male breast cancer is very rare (usually subareolar), a significant proportion of cases are linked to BRCA2 mutations.'),
    (v_topic_id, '214. Which syndrome involves a germline mutation in p53, leading to breast cancer, sarcomas, leukemias, and brain tumors at a very young age?', '["Lynch Syndrome", "Li-Fraumeni Syndrome", "Peutz-Jeghers Syndrome", "Cowden Syndrome"]', 1, 'Li-Fraumeni is a devastating cancer predisposition syndrome caused by a single hit to p53 in the germline.'),
    (v_topic_id, '215. A sentinel lymph node biopsy is performed during breast cancer surgery. If the sentinel node is NEGATIVE for tumor cells, what does this imply?', '["The patient is cured", "The rest of the axillary nodes are highly likely to be negative, sparing the patient a full axillary dissection", "The tumor has spread hematogenously", "The tumor is ER positive"]', 1, 'The sentinel node is the very first node the tumor drains to. If it is clean, the rest are assumed clean, preventing the severe lymphedema caused by removing all the armpit nodes.'),
    
    -- BREAST: MALE BREAST & GYNECOMASTIA (216-225)
    (v_topic_id, '216. Gynecomastia is the enlargement of the male breast. What is the fundamental hormonal cause?', '["Excess androgens", "An imbalance of estrogens to androgens (relative estrogen excess)", "Low prolactin", "High progesterone"]', 1, 'Any state that increases estrogen or decreases testosterone can cause gynecomastia.'),
    (v_topic_id, '217. Which physiological stages normally feature transient gynecomastia?', '["Neonatal period, Puberty, and Old Age", "Only during puberty", "Only in old age", "Never, it is always pathological"]', 0, 'Neonatal (maternal estrogens), Puberty (estrogen peaks before testosterone), and Old Age (testosterone drops, aromatase in fat increases estrogen).'),
    (v_topic_id, '218. Cirrhosis of the liver can cause severe gynecomastia. Why?', '["The liver produces excess estrogen", "The liver fails to metabolize and clear circulating estrogens", "The liver secretes hCG", "The liver destroys testosterone"]', 1, 'Failing livers cannot break down estrogens, leading to hyperestrinism (spider angiomas, palmar erythema, gynecomastia).'),
    (v_topic_id, '219. Which genetic syndrome in males (47, XXY) classically presents with gynecomastia, testicular atrophy, and tall stature?', '["Turner Syndrome", "Klinefelter Syndrome", "Marfan Syndrome", "Kallmann Syndrome"]', 1, 'Klinefelter syndrome involves primary testicular failure, leading to high FSH/LH, high estrogen, and severe gynecomastia.'),
    (v_topic_id, '220. Which of the following drugs is famous for causing gynecomastia as a side effect?', '["Spironolactone", "Aspirin", "Metoprolol", "Lisinopril"]', 0, 'Spironolactone is an androgen receptor antagonist and also slightly increases estrogen conversion (Some Drugs Create Awesome Knockers: Spironolactone, Digoxin, Cimetidine, Alcohol, Ketoconazole).'),
    (v_topic_id, '221. Male breast cancer accounts for <1% of all breast cancers. What is the most common histological type?', '["Invasive Lobular Carcinoma", "Invasive Ductal Carcinoma", "Medullary Carcinoma", "Fibroadenoma"]', 1, 'Male breasts have ducts but very few lobules, so almost all male breast cancers are Ductal.'),
    (v_topic_id, '222. Where does male breast cancer typically present?', '["In the tail of Spence", "As a subareolar mass often with nipple discharge", "Deep in the pectoralis muscle", "In the axilla"]', 1, 'Because the male breast has very little tissue, the ducts are concentrated directly under the nipple (subareolar).'),
    (v_topic_id, '223. What is the primary reason male breast cancer often presents at a higher clinical stage (more advanced) than female breast cancer?', '["It is biologically more aggressive", "Lack of screening and very little breast tissue means it invades the skin and chest wall much faster", "It doesn''t respond to Tamoxifen", "Men ignore symptoms completely"]', 1, 'The lack of thick breast tissue means the tumor rapidly hits the overlying skin or underlying muscle/lymphatics.'),
    (v_topic_id, '224. Fibrocystic change is the most common cause of breast lumps in premenopausal women. How does the pain typically behave?', '["It is constant throughout the month", "It worsens cyclically in the premenstrual (luteal) phase and resolves with menses", "It only occurs during ovulation", "It is entirely painless"]', 1, 'The cysts swell in response to progesterone during the luteal phase, stretching the tissue and causing pain.'),
    (v_topic_id, '225. A lactating woman develops a fluctuant, tender, warm mass in her breast with a fever. Antibiotics do not resolve it. What is the next step?', '["Incision and drainage of a breast abscess", "Mastectomy", "Mammogram", "Reassurance"]', 0, 'If acute mastitis progresses to an abscess (walled-off collection of pus), antibiotics cannot penetrate it. It must be surgically drained.');

    RAISE NOTICE 'SUCCESS: Reproductive Pathology MCQs P3 (161-240) registered.';
END $$;

COMMIT;
